public class DefaultKeyedValues_removeValue_TriageGen1Test {

    private DefaultKeyedValues keyedValues;

    @Before
    public void setUp() {
        keyedValues = new DefaultKeyedValues();
    }

    /**
     * Tests removing a value that exists in the collection.
     * This covers the standard successful execution path.
     */
    @Test
    public void testRemoveValue_ExistingKey() {
        String key1 = "A";
        String key2 = "B";
        double val1 = 10.0;
        double val2 = 20.0;

        keyedValues.addValue(key1, val1);
        keyedValues.addValue(key2, val2);

        assertEquals(2, keyedValues.getItemCount());

        // Action
        keyedValues.removeValue(key1);

        // Assertions
        assertEquals(1, keyedValues.getItemCount());
        assertEquals(key2, keyedValues.getKey(0));
        assertEquals(val2, keyedValues.getValue(0).doubleValue(), 0.0001);
    }





